1	//! Pure argv construction for "publish a package to its registry", plus
2	//! subprocess-output classification for the same three ecosystems (Cargo,
3	//! npm, PyPI).
4	//!
5	//! This module owns exactly two questions per ecosystem: *what command do we
6	//! run* (given package/plan facts and already-detected environment facts --
7	//! never a [`callisto_model::CommandRunner`] call of its own) and *what did
8	//! the finished command's output mean*. Actually invoking the command, and
9	//! any retry/backoff policy around a failed attempt, is the caller's job --
10	//! see the durable release executor's single production publish path.
11	//!
12	//! A small amount of local filesystem reading happens here (the Cargo
13	//! on-disk version check, npm package-manager detection from lockfiles, the
14	//! PyPI interpreter's PATH lookup) -- that's "gathering the facts needed to
15	//! build the right argv", not executing a publish. It never shells out.
16	
17	use std::ffi::OsStr;
18	use std::path::{Path, PathBuf};
19	use std::time::Duration;
20	
21	use callisto_manifests::WorkspaceCargoResolver;
22	use callisto_model::{CommandOutput, Ecosystem, NpmAccess, PackageId, PublishOutcome, RegistryError, Version};
23	
24	use crate::error::{GraphError, ReleasePreconditionRequirement};
25	
26	/// Default fallback wait (seconds) when a registry does not supply a
27	/// `retry_after` value and the classifier cannot parse one from output.
28	const DEFAULT_RATE_LIMIT_WAIT_SECS: u64 = 60;
29	
30	/// One subprocess invocation: program, args, and working directory. Building
31	/// this is the entire job of the `*_publish_argv` functions below --
32	/// executing it is the caller's.
33	#[derive(Debug, Clone, PartialEq, Eq)]
34	pub struct Argv {
35	    pub program: String,
36	    pub args: Vec<String>,
37	    pub cwd: PathBuf,
38	}
39	
40	// ---------------------------------------------------------------- cargo
41	
42	/// Builds the exact `cargo publish` argv for one crate: `--manifest-path`
43	/// (so the caller can keep the workspace root as its own working directory)
44	/// plus `--locked`, so a stale `Cargo.lock` fails the publish immediately
45	/// instead of `cargo` silently re-resolving one at publish time.
46	/// `registry_key` is `Some` only for a non-default registry -- crates.io is
47	/// the implicit default and never needs `--registry`.
48	///
49	/// Before returning, verifies that the on-disk `Cargo.toml` version under
50	/// `package_dir` (resolving `version.workspace = true` against the
51	/// workspace root's `[workspace.package].version` when present) matches
52	/// `version` -- this is the one behavior `SubprocessRegistryClient` had that
53	/// the durable release executor's own `dispatch_registry` had silently
54	/// dropped: it catches the common mistake of running `release execute`
55	/// without first running `callisto version`, which would otherwise silently
56	/// publish the old on-disk version.
57	pub fn cargo_publish_argv(
58	    workspace_root: &Path,
59	    package_dir: &Path,
60	    package_name: &str,
61	    version: &Version,
62	    registry_key: Option<&str>,
63	) -> Result<Argv, GraphError> {
64	    verify_cargo_ondisk_version(workspace_root, package_dir, package_name, version)?;
65	
66	    let manifest_path = workspace_root.join(package_dir).join("Cargo.toml");
67	    let mut args = vec![
68	        "publish".to_string(),
69	        "--manifest-path".to_string(),
70	        manifest_path.to_string_lossy().into_owned(),
71	        "--locked".to_string(),
72	    ];
73	    if let Some(reg) = registry_key {
74	        args.push("--registry".to_string());
75	        args.push(reg.to_string());
76	    }
77	    Ok(Argv {
78	        program: "cargo".to_string(),
79	        args,
80	        cwd: cargo_workspace_dir(workspace_root, package_dir)?,
81	    })
82	}
83	
84	/// The directory of the Cargo workspace the package at `package_dir` belongs to. Cargo reads `.cargo/config.toml`
85	/// (registries, credentials) from where it runs, so a command about the package runs here, not at the workspace root.
86	pub(crate) fn cargo_workspace_dir(workspace_root: &Path, package_dir: &Path) -> Result<PathBuf, GraphError> {
87	    let root_manifest = callisto_manifests::cargo_workspace_of(
88	        &mut callisto_manifests::WorkspaceReads::default(),
89	        workspace_root,
90	        &package_dir.join("Cargo.toml"),
91	    )?;
92	    Ok(workspace_root.join(root_manifest.parent().unwrap_or(Path::new(""))))
93	}
94	
95	fn verify_cargo_ondisk_version(
96	    workspace_root: &Path,
97	    package_dir: &Path,
98	    package_name: &str,
99	    planned: &Version,
100	) -> Result<(), GraphError> {
101	    let manifest_path = workspace_root.join(package_dir).join("Cargo.toml");
102	    let contents = std::fs::read_to_string(&manifest_path).map_err(|error| GraphError::ReleaseInputRead {
103	        path: manifest_path.clone(),
104	        message: error.to_string(),
105	    })?;
106	    // Read `version` via `toml::Value`: `version.workspace = true` makes it a table, not a string.
107	    let parsed = toml::from_str::<toml::Value>(&contents).map_err(|error| GraphError::ReleaseInputRead {
108	        path: manifest_path.clone(),
109	        message: error.to_string(),
110	    })?;
111	    let version_value =
112	        parsed
113	            .get("package")
114	            .and_then(|p| p.get("version"))
115	            .ok_or_else(|| GraphError::ReleaseInputRead {
116	                path: manifest_path.clone(),
117	                message: "missing [package].version".to_string(),
118	            })?;
119	
120	    let on_disk = if let Some(s) = version_value.as_str() {
121	        s.to_string()
122	    } else if version_value.get("workspace").and_then(toml::Value::as_bool) == Some(true) {
123	        let member = package_dir.join("Cargo.toml");
124	        let document = callisto_manifests::parse_manifest(&member, &contents)?;
125	        let root_manifest = callisto_manifests::enclosing_workspace_manifest(workspace_root, &member, &document)?
126	            .ok_or_else(|| GraphError::ReleaseInputRead {
127	                path: manifest_path.clone(),
128	                message: "`version.workspace = true` but no Cargo workspace governs it".to_string(),
129	            })?;
130	        let root_manifest_path = workspace_root.join(&root_manifest);
131	        let resolver = WorkspaceCargoResolver::load_at(workspace_root, &root_manifest)?;
132	        let ws_version = resolver
133	            .workspace_version()?
134	            .ok_or_else(|| GraphError::ReleaseInputRead {
135	                path: root_manifest_path.clone(),
136	                message: "`version.workspace = true` but the workspace root has no [workspace.package].version"
137	                    .to_string(),
138	            })?;
139	        ws_version.render().to_string()
140	    } else {
141	        return Err(GraphError::ReleaseInputRead {
142	            path: manifest_path,
143	            message: "[package].version is neither a string nor a `{ workspace = true }` table".to_string(),
144	        });
145	    };
146	
147	    let found = Version::parse(&on_disk, planned.grammar())?;
148	    if found != *planned {
149	        return Err(GraphError::OnDiskVersionDrift {
150	            package: PackageId::Prefixed {
151	                ecosystem: Ecosystem::Cargo,
152	                name: package_name.to_string(),
153	            },
154	            expected: planned.clone(),
155	            found,
156	        });
157	    }
158	    Ok(())
159	}
160	
161	// ------------------------------------------------------------------ npm
162	
163	/// The npm-compatible package manager a workspace uses, detected from
164	/// lockfile presence. Each one needs a materially different invocation to
165	/// publish a single named package out of a monorepo -- see
166	/// [`npm_publish_argv`].
167	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
168	pub enum NpmPackageManager {
169	    Pnpm,
170	    Yarn,
171	    Bun,
172	    Npm,
173	}
174	
175	/// Detects the npm-compatible package manager of the workspace in `workspace_dir` from the files that mark it.
176	/// Detection priority: pnpm > yarn > bun > npm (default). A `pnpm-workspace.yaml` is pnpm even where the lockfile is not
177	/// committed, and a file that cannot be inspected is an error, not a reason to fall back to `npm`.
178	///
179	/// The package manager comes from the workspace, so a pnpm or yarn workspace publishes with its own tool, not
180	/// plain `npm publish`.
181	///
182	/// # Errors
183	///
184	/// A marker file cannot be inspected.
185	pub fn detect_npm_package_manager(workspace_dir: &Path) -> Result<NpmPackageManager, GraphError> {
186	    let present = |name: &str| -> Result<bool, GraphError> {
187	        let path = workspace_dir.join(name);
188	        callisto_model::strict_fs::exists(&path).map_err(|error| GraphError::ReleaseInputRead {
189	            path,
190	            message: error.to_string(),
191	        })
192	    };
193	    Ok(if present("pnpm-lock.yaml")? || present("pnpm-workspace.yaml")? {
194	        NpmPackageManager::Pnpm
195	    } else if present("yarn.lock")? {
196	        NpmPackageManager::Yarn
197	    } else if present("bun.lockb")? || present("bun.lock")? {
198	        // bun.lockb is the legacy binary lockfile format; bun.lock (text) is
199	        // written by Bun >= 1.1.1. Both signal a bun-managed workspace.
200	        NpmPackageManager::Bun
201	    } else {
202	        NpmPackageManager::Npm
203	    })
204	}
205	
206	/// Builds the npm-ecosystem publish argv for one package, given the
207	/// already-detected `package_manager` (see [`detect_npm_package_manager`]).
208	///
209	/// | Package manager | Program | Base args                                  |
210	/// |------------------|---------|--------------------------------------------|
211	/// | Pnpm             | `pnpm`  | `publish --filter=<name> --no-git-checks`  |
212	/// | Yarn             | `yarn`  | `workspace <name> npm publish`             |
213	/// | Bun              | `bun`   | `publish` (run from `package_dir`)         |
214	/// | Npm              | `npm`   | `publish --workspace=<name>`               |
215	///
216	/// `--filter=`/`--workspace=` use the joined form so the name cannot be
217	/// re-read as an option. Yarn takes the name positionally and has no joined
218	/// spelling, so there it rests on `ReleasePackageId`'s leading-`-` rejection.
219	///
220	/// `tag`/`access`/`registry` are appended to every variant's base args.
221	/// `package_dir` is only used for bun: it has no `--filter`/`--workspace`
222	/// flag to target one package by name, so it alone must run from the
223	/// package's own directory rather than the workspace root.
224	pub fn npm_publish_argv(
225	    workspace_root: &Path,
226	    package_dir: &Path,
227	    package_name: &str,
228	    package_manager: NpmPackageManager,
229	    tag: Option<&str>,
230	    access: Option<NpmAccess>,
231	    registry: Option<&str>,
232	) -> Argv {
233	    // `yarn npm publish` has no `--registry` option (it rejects one); the publish step refuses a configured registry
234	    // for yarn before it gets here, so nothing is dropped silently.
235	    let registry = registry.filter(|_| !matches!(package_manager, NpmPackageManager::Yarn));
236	    let extra = npm_publish_flags(package_name, tag, access, registry);
237	
238	    let (program, mut args, cwd) = match package_manager {
239	        NpmPackageManager::Pnpm => (
240	            "pnpm",
241	            vec![
242	                "publish".to_string(),
243	                // `--filter=<name>`, not `--filter <name>`: the joined form
244	                // cannot be re-read as an option even if a name slipped past
245	                // `ReleasePackageId`'s charset rule.
246	                format!("--filter={package_name}"),
247	                // pnpm >= 7 refuses a dirty tree, and the tree is dirty after `callisto version` stages bumps.
248	                "--no-git-checks".to_string(),
249	            ],
250	            workspace_root.to_path_buf(),
251	        ),
252	        NpmPackageManager::Yarn => (
253	            "yarn",
254	            vec![
255	                "workspace".to_string(),
256	                package_name.to_string(),
257	                "npm".to_string(),
258	                "publish".to_string(),
259	            ],
260	            workspace_root.to_path_buf(),
261	        ),
262	        NpmPackageManager::Bun => ("bun", vec!["publish".to_string()], workspace_root.join(package_dir)),
263	        NpmPackageManager::Npm => (
264	            "npm",
265	            vec!["publish".to_string(), format!("--workspace={package_name}")],
266	            workspace_root.to_path_buf(),
267	        ),
268	    };
269	    args.extend(extra);
270	    Argv {
271	        program: program.to_string(),
272	        args,
273	        cwd,
274	    }
275	}
276	
277	/// The access an npm package publishes with: the explicit `publishConfig.access`,
278	/// else `public` for a scoped `@scope/name` (npm defaults scoped packages to restricted).
279	pub fn npm_default_access(name: &str, explicit: Option<NpmAccess>) -> Option<NpmAccess> {
280	    explicit.or_else(|| name.starts_with('@').then_some(NpmAccess::Public))
281	}
282	
283	/// `--tag`/`--access`/`--registry`, shared by every npm-ecosystem publish argv.
284	fn npm_publish_flags(
285	    package_name: &str,
286	    tag: Option<&str>,
287	    access: Option<NpmAccess>,
288	    registry: Option<&str>,
289	) -> Vec<String> {
290	    let mut extra: Vec<String> = Vec::new();
291	    if let Some(t) = tag {
292	        extra.push("--tag".to_string());
293	        extra.push(t.to_string());
294	    }
295	    if let Some(access) = npm_default_access(package_name, access) {
296	        extra.push("--access".to_string());
297	        extra.push(
298	            match access {
299	                NpmAccess::Public => "public",
300	                NpmAccess::Restricted => "restricted",
301	            }
302	            .to_string(),
303	        );
304	    }
305	    if let Some(reg) = registry {
306	        extra.push("--registry".to_string());
307	        extra.push(reg.to_string());
308	    }
309	    extra
310	}
311	
312	/// Publishes the package in `package_dir` by path: `npm publish <dir>` from `workspace_dir` (the workspace that owns
313	/// it, where its `.npmrc` is read), whatever the package manager. pnpm `--filter`, yarn
314	/// `workspace`, and npm `--workspace` select only workspace members, and an npm
315	/// platform package directory usually is not one. The path is absolute, so it
316	/// cannot be read as an option.
317	pub fn npm_publish_directory_argv(
318	    workspace_root: &Path,
319	    workspace_dir: &Path,
320	    package_dir: &Path,
321	    package_name: &str,
322	    tag: Option<&str>,
323	    access: Option<NpmAccess>,
324	    registry: Option<&str>,
325	) -> Argv {
326	    let mut args = vec![
327	        "publish".to_string(),
328	        workspace_root.join(package_dir).to_string_lossy().into_owned(),
329	    ];
330	    args.extend(npm_publish_flags(package_name, tag, access, registry));
331	    Argv {
332	        program: "npm".to_string(),
333	        args,
334	        cwd: workspace_root.join(workspace_dir),
335	    }
336	}
337	
338	// ----------------------------------------------------------------- pypi
339	
340	/// `python -m build --sdist --wheel --outdir <outdir>` in the package directory, with the first interpreter on PATH
341	/// and `SOURCE_DATE_EPOCH` set so backends that honor it stamp the same time into every rebuild.
342	pub fn pypi_build_argv(
343	    workspace_root: &Path,
344	    package_dir: &Path,
345	    outdir: &Path,
346	    source_date_epoch: u64,
347	) -> Result<Argv, GraphError> {
348	    let interpreter = resolve_python_interpreter(std::env::var_os("PATH").as_deref())?;
349	    Ok(Argv {
350	        program: "env".to_string(),
351	        args: vec![
352	            format!("SOURCE_DATE_EPOCH={source_date_epoch}"),
353	            interpreter.to_string(),
354	            "-m".to_string(),
355	            "build".to_string(),
356	            "--sdist".to_string(),
357	            "--wheel".to_string(),
358	            "--outdir".to_string(),
359	            outdir.to_string_lossy().into_owned(),
360	        ],
361	        cwd: workspace_root.join(package_dir),
362	    })
363	}
364	
365	/// `twine upload` of exactly `files`, never a glob or `--skip-existing`, which skips by name without comparing bytes.
366	pub fn pypi_upload_argv(workspace_root: &Path, package_dir: &Path, index: Option<&str>, files: &[PathBuf]) -> Argv {
367	    let mut args = vec!["upload".to_string()];
368	    if let Some(index) = index {
369	        args.push("--repository-url".to_string());
370	        args.push(index.to_string());
371	    }
372	    args.extend(files.iter().map(|file| file.to_string_lossy().into_owned()));
373	    Argv {
374	        program: "twine".to_string(),
375	        args,
376	        cwd: workspace_root.join(package_dir),
377	    }
378	}
379	
380	/// Resolves the interpreter for the PyPI build step's `python -m build`:
381	/// prefers `python3` -- the only name macOS and Debian systems guarantee --
382	/// and falls back to bare `python` for systems that only ship that. Errors
383	/// naming both when neither is on `path_value`.
384	///
385	/// `path_value` is injected rather than read from `$PATH` directly so tests
386	/// can exercise both resolutions and the error without mutating process-wide
387	/// environment state.
388	fn resolve_python_interpreter(path_value: Option<&OsStr>) -> Result<&'static str, GraphError> {
389	    if exists_on_path("python3", path_value) {
390	        Ok("python3")
391	    } else if exists_on_path("python", path_value) {
392	        Ok("python")
393	    } else {
394	        Err(GraphError::ReleasePreconditionUnmet {
395	            requirement: ReleasePreconditionRequirement::PythonInterpreterOnPath,
396	        })
397	    }
398	}
399	
400	/// Whether `program` exists as a file in some directory of `path_value` --
401	/// PATH-lookup semantics, without ever spawning it.
402	fn exists_on_path(program: &str, path_value: Option<&OsStr>) -> bool {
403	    path_value.is_some_and(|path| std::env::split_paths(path).any(|dir| dir.join(program).is_file()))
404	}
405	
406	// ---- shared output-classification helpers --------------------------------
407	
408	fn combined_lower(output: &CommandOutput) -> String {
409	    format!("{}\n{}", output.stdout, output.stderr).to_lowercase()
410	}
411	
412	/// What a failed publish said: the last lines of redacted stdout, then redacted stderr. pnpm and twine print their
413	/// errors to stdout, so stderr alone can leave the failure message empty.
414	fn failure_detail(output: &CommandOutput) -> String {
415	    const STDOUT_TAIL_LINES: usize = 8;
416	    let stdout = callisto_model::redact_command_stderr(&output.stdout);
417	    let tail: Vec<&str> = stdout.lines().rev().take(STDOUT_TAIL_LINES).collect();
418	    let tail = tail.into_iter().rev().collect::<Vec<_>>().join("\n");
419	    let stderr = output.redacted_stderr();
420	    [tail.trim(), stderr.trim()]
421	        .into_iter()
422	        .filter(|part| !part.is_empty())
423	        .collect::<Vec<_>>()
424	        .join("\n")
425	}
426	
427	/// Parses a numeric retry-after value (seconds) as reported by a registry
428	/// tool's output.
429	fn parse_retry_after(raw: &str) -> Option<Duration> {
430	    raw.trim().parse::<u64>().ok().map(Duration::from_secs)
431	}
432	
433	/// Looks for a `retry after <N>` mention in already-lowercased text and
434	/// parses `<N>` as a whole-second duration.
435	fn extract_retry_after_duration(text_lower: &str) -> Option<Duration> {
436	    const NEEDLE: &str = "retry after ";
437	    let idx = text_lower.find(NEEDLE)?;
438	    let rest = &text_lower[idx + NEEDLE.len()..];
439	    let token = rest.split_whitespace().next()?;
440	    let digits: String = token.chars().take_while(|c| c.is_ascii_digit()).collect();
441	    if digits.is_empty() {
442	        return None;
443	    }
444	    parse_retry_after(&digits)
445	}
446	
447	fn detect_rate_limit(text_lower: &str) -> Option<RegistryError> {
448	    // Match rate-limit text with context; a bare "429" appears in cargo's size output ("429.1KiB").
449	    let is_rate_limited = text_lower.contains("too many requests")
450	        || text_lower.contains("rate limit")
451	        || text_lower.contains("erate_limit")
452	        || (text_lower.contains("429")
453	            && (text_lower.contains("too many") || text_lower.contains("rate") || text_lower.contains("retry")));
454	    if is_rate_limited {
455	        let dur = extract_retry_after_duration(text_lower).unwrap_or(Duration::from_secs(DEFAULT_RATE_LIMIT_WAIT_SECS));
456	        Some(RegistryError::RateLimited(dur))
457	    } else {
458	        None
459	    }
460	}
461	
462	fn detect_auth_failure(text_lower: &str, raw_stderr: &CommandOutput) -> Option<RegistryError> {
463	    // Match 401/403 with context, like the 429 guard; byte counts and timings contain those digits.
464	    if (text_lower.contains("401") && text_lower.contains("auth"))
465	        || (text_lower.contains("403") && (text_lower.contains("auth") || text_lower.contains("forbidden")))
466	        || text_lower.contains("authentication")
467	        || text_lower.contains("not logged in")
468	        || text_lower.contains("invalid token")
469	        || text_lower.contains("forbidden")
470	    {
471	        Some(RegistryError::AuthFailed(raw_stderr.redacted_stderr()))
472	    } else {
473	        None
474	    }
475	}
476	
477	/// Classifies combined `cargo publish` output into a [`PublishOutcome`] or
478	/// [`RegistryError`].
479	pub(crate) fn classify_cargo_output(output: &CommandOutput) -> Result<PublishOutcome, RegistryError> {
480	    let combined = combined_lower(output);
481	
482	    // Success first: only a failed publish can mean the version is already there, and a successful one may print
483	    // anything, including those words.
484	    if output.success() {
485	        return Ok(PublishOutcome::Published);
486	    }
487	    if combined.contains("already exists") || combined.contains("already uploaded") {
488	        return Ok(PublishOutcome::AlreadyPublished);
489	    }
490	    if let Some(err) = detect_rate_limit(&combined) {
491	        return Err(err);
492	    }
493	    if let Some(err) = detect_auth_failure(&combined, output) {
494	        return Err(err);
495	    }
496	    Err(RegistryError::Other(format!(
497	        "cargo publish failed (exit {:?}): {}",
498	        output.exit_code,
499	        failure_detail(output)
500	    )))
501	}
502	
503	/// Classifies combined `npm publish` (or `pnpm`/`yarn`/`bun` equivalent)
504	/// output into a [`PublishOutcome`] or [`RegistryError`].
505	pub(crate) fn classify_npm_publish_output(output: &CommandOutput) -> Result<PublishOutcome, RegistryError> {
506	    let combined = combined_lower(output);
507	
508	    // Success first, as for cargo. On failure only npm's own conflict signals count: a bare `e409` can sit in a bundle
509	    // name or hash.
510	    if output.success() {
511	        return Ok(PublishOutcome::Published);
512	    }
513	    if combined.contains("code e409")
514	        || combined.contains("code epublishconflict")
515	        || combined.contains("cannot publish over the previously published versions")
516	    {
517	        return Ok(PublishOutcome::AlreadyPublished);
518	    }
519	    if let Some(err) = detect_rate_limit(&combined) {
520	        return Err(err);
521	    }
522	    if let Some(err) = detect_auth_failure(&combined, output) {
523	        return Err(err);
524	    }
525	    Err(RegistryError::Other(format!(
526	        "npm publish failed (exit {:?}): {}",
527	        output.exit_code,
528	        failure_detail(output)
529	    )))
530	}
531	
532	/// Classifies combined `twine upload` output into a [`PublishOutcome`] or
533	/// [`RegistryError`].
534	///
535	/// Priority order (highest wins):
536	/// 1. A successful run printing `"already exist"` (twine's `--skip-existing` message) without `"uploading"` ->
537	///    [`PublishOutcome::AlreadyPublished`]. Callisto passes no `--skip-existing`, so a conflict is a failing run and
538	///    falls through to `RegistryError::Other` below, which is the intended fail-closed outcome.
539	/// 2. Zero exit code with no skip-only mention -> [`PublishOutcome::Published`].
540	/// 3. Rate-limit signal (`429`, `too many requests`, `rate limit`) ->
541	///    [`RegistryError::RateLimited`] with a parsed or default 60-second
542	///    retry-after duration.
543	/// 4. Auth-failure signal (`401`, `403`, `authentication`, etc.) ->
544	///    [`RegistryError::AuthFailed`].
545	/// 5. Anything else -> [`RegistryError::Other`].
546	pub(crate) fn classify_twine_output(output: &CommandOutput) -> Result<PublishOutcome, RegistryError> {
547	    let combined = combined_lower(output);
548	
549	    let has_skip = combined.contains("already exist");
550	    let has_upload = combined.contains("uploading");
551	    if has_skip && !has_upload && output.success() {
552	        return Ok(PublishOutcome::AlreadyPublished);
553	    }
554	    if output.success() {
555	        return Ok(PublishOutcome::Published);
556	    }
557	    if let Some(err) = detect_rate_limit(&combined) {
558	        return Err(err);
559	    }
560	    if let Some(err) = detect_auth_failure(&combined, output) {
561	        return Err(err);
562	    }
563	    Err(RegistryError::Other(format!(
564	        "twine upload failed (exit {:?}): {}",
565	        output.exit_code,
566	        failure_detail(output)
567	    )))
568	}
