//! Pure argv construction for "publish a package to its registry", plus
//! subprocess-output classification for the same three ecosystems (Cargo,
//! npm, PyPI).
//!
//! This module owns exactly two questions per ecosystem: *what command do we
//! run* (given package/plan facts and already-detected environment facts --
//! never a [`callisto_model::CommandRunner`] call of its own) and *what did
//! the finished command's output mean*. Actually invoking the command, and
//! any retry/backoff policy around a failed attempt, is the caller's job --
//! see the durable release executor's single production publish path.
//!
//! A small amount of local filesystem reading happens here (the Cargo
//! on-disk version check, npm package-manager detection from lockfiles, the
//! PyPI interpreter's PATH lookup) -- that's "gathering the facts needed to
//! build the right argv", not executing a publish. It never shells out.

use std::ffi::OsStr;
use std::path::{Path, PathBuf};
use std::time::Duration;

use callisto_manifests::WorkspaceCargoResolver;
use callisto_model::{CommandOutput, Ecosystem, NpmAccess, PackageId, PublishOutcome, RegistryError, Version};

use crate::error::{GraphError, ReleasePreconditionRequirement};

/// Default fallback wait (seconds) when a registry does not supply a
/// `retry_after` value and the classifier cannot parse one from output.
const DEFAULT_RATE_LIMIT_WAIT_SECS: u64 = 60;

/// One subprocess invocation: program, args, and working directory. Building
/// this is the entire job of the `*_publish_argv` functions below --
/// executing it is the caller's.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Argv {
    pub program: String,
    pub args: Vec<String>,
    pub cwd: PathBuf,
}

// ---------------------------------------------------------------- cargo

/// Builds the exact `cargo publish` argv for one crate: `--manifest-path`
/// (so the caller can keep the workspace root as its own working directory)
/// plus `--locked`, so a stale `Cargo.lock` fails the publish immediately
/// instead of `cargo` silently re-resolving one at publish time.
/// `registry_key` is `Some` only for a non-default registry -- crates.io is
/// the implicit default and never needs `--registry`.
///
/// Before returning, verifies that the on-disk `Cargo.toml` version under
/// `package_dir` (resolving `version.workspace = true` against the
/// workspace root's `[workspace.package].version` when present) matches
/// `version` -- this is the one behavior `SubprocessRegistryClient` had that
/// the durable release executor's own `dispatch_registry` had silently
/// dropped: it catches the common mistake of running `release execute`
/// without first running `callisto version`, which would otherwise silently
/// publish the old on-disk version.
pub fn cargo_publish_argv(
    workspace_root: &Path,
    package_dir: &Path,
    package_name: &str,
    version: &Version,
    registry_key: Option<&str>,
) -> Result<Argv, GraphError> {
    verify_cargo_ondisk_version(workspace_root, package_dir, package_name, version)?;

    let manifest_path = workspace_root.join(package_dir).join("Cargo.toml");
    let mut args = vec![
        "publish".to_string(),
        "--manifest-path".to_string(),
        manifest_path.to_string_lossy().into_owned(),
        "--locked".to_string(),
    ];
    if let Some(reg) = registry_key {
        args.push("--registry".to_string());
        args.push(reg.to_string());
    }
    Ok(Argv {
        program: "cargo".to_string(),
        args,
        cwd: cargo_workspace_dir(workspace_root, package_dir)?,
    })
}

/// The directory of the Cargo workspace the package at `package_dir` belongs to. Cargo reads `.cargo/config.toml`
/// (registries, credentials) from where it runs, so a command about the package runs here, not at the workspace root.
pub(crate) fn cargo_workspace_dir(workspace_root: &Path, package_dir: &Path) -> Result<PathBuf, GraphError> {
    let root_manifest = callisto_manifests::cargo_workspace_of(
        &mut callisto_manifests::WorkspaceReads::default(),
        workspace_root,
        &package_dir.join("Cargo.toml"),
    )?;
    Ok(workspace_root.join(root_manifest.parent().unwrap_or(Path::new(""))))
}

fn verify_cargo_ondisk_version(
    workspace_root: &Path,
    package_dir: &Path,
    package_name: &str,
    planned: &Version,
) -> Result<(), GraphError> {
    let manifest_path = workspace_root.join(package_dir).join("Cargo.toml");
    let contents = std::fs::read_to_string(&manifest_path).map_err(|error| GraphError::ReleaseInputRead {
        path: manifest_path.clone(),
        message: error.to_string(),
    })?;
    // Read `version` via `toml::Value`: `version.workspace = true` makes it a table, not a string.
    let parsed = toml::from_str::<toml::Value>(&contents).map_err(|error| GraphError::ReleaseInputRead {
        path: manifest_path.clone(),
        message: error.to_string(),
    })?;
    let version_value =
        parsed
            .get("package")
            .and_then(|p| p.get("version"))
            .ok_or_else(|| GraphError::ReleaseInputRead {
                path: manifest_path.clone(),
                message: "missing [package].version".to_string(),
            })?;

    let on_disk = if let Some(s) = version_value.as_str() {
        s.to_string()
    } else if version_value.get("workspace").and_then(toml::Value::as_bool) == Some(true) {
        let member = package_dir.join("Cargo.toml");
        let document = callisto_manifests::parse_manifest(&member, &contents)?;
        let root_manifest = callisto_manifests::enclosing_workspace_manifest(workspace_root, &member, &document)?
            .ok_or_else(|| GraphError::ReleaseInputRead {
                path: manifest_path.clone(),
                message: "`version.workspace = true` but no Cargo workspace governs it".to_string(),
            })?;
        let root_manifest_path = workspace_root.join(&root_manifest);
        let resolver = WorkspaceCargoResolver::load_at(workspace_root, &root_manifest)?;
        let ws_version = resolver
            .workspace_version()?
            .ok_or_else(|| GraphError::ReleaseInputRead {
                path: root_manifest_path.clone(),
                message: "`version.workspace = true` but the workspace root has no [workspace.package].version"
                    .to_string(),
            })?;
        ws_version.render().to_string()
    } else {
        return Err(GraphError::ReleaseInputRead {
            path: manifest_path,
            message: "[package].version is neither a string nor a `{ workspace = true }` table".to_string(),
        });
    };

    let found = Version::parse(&on_disk, planned.grammar())?;
    if found != *planned {
        return Err(GraphError::OnDiskVersionDrift {
            package: PackageId::Prefixed {
                ecosystem: Ecosystem::Cargo,
                name: package_name.to_string(),
            },
            expected: planned.clone(),
            found,
        });
    }
    Ok(())
}

// ------------------------------------------------------------------ npm

/// The npm-compatible package manager a workspace uses, detected from
/// lockfile presence. Each one needs a materially different invocation to
/// publish a single named package out of a monorepo -- see
/// [`npm_publish_argv`].
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum NpmPackageManager {
    Pnpm,
    Yarn,
    Bun,
    Npm,
}

/// Detects the npm-compatible package manager of the workspace in `workspace_dir` from the files that mark it.
/// Detection priority: pnpm > yarn > bun > npm (default). A `pnpm-workspace.yaml` is pnpm even where the lockfile is not
/// committed, and a file that cannot be inspected is an error, not a reason to fall back to `npm`.
///
/// The package manager comes from the workspace, so a pnpm or yarn workspace publishes with its own tool, not
/// plain `npm publish`.
///
/// # Errors
///
/// A marker file cannot be inspected.
pub fn detect_npm_package_manager(workspace_dir: &Path) -> Result<NpmPackageManager, GraphError> {
    let present = |name: &str| -> Result<bool, GraphError> {
        let path = workspace_dir.join(name);
        callisto_model::strict_fs::exists(&path).map_err(|error| GraphError::ReleaseInputRead {
            path,
            message: error.to_string(),
        })
    };
    Ok(if present("pnpm-lock.yaml")? || present("pnpm-workspace.yaml")? {
        NpmPackageManager::Pnpm
    } else if present("yarn.lock")? {
        NpmPackageManager::Yarn
    } else if present("bun.lockb")? || present("bun.lock")? {
        // bun.lockb is the legacy binary lockfile format; bun.lock (text) is
        // written by Bun >= 1.1.1. Both signal a bun-managed workspace.
        NpmPackageManager::Bun
    } else {
        NpmPackageManager::Npm
    })
}

/// Builds the npm-ecosystem publish argv for one package, given the
/// already-detected `package_manager` (see [`detect_npm_package_manager`]).
///
/// | Package manager | Program | Base args                                  |
/// |------------------|---------|--------------------------------------------|
/// | Pnpm             | `pnpm`  | `publish --filter=<name> --no-git-checks`  |
/// | Yarn             | `yarn`  | `workspace <name> npm publish`             |
/// | Bun              | `bun`   | `publish` (run from `package_dir`)         |
/// | Npm              | `npm`   | `publish --workspace=<name>`               |
///
/// `--filter=`/`--workspace=` use the joined form so the name cannot be
/// re-read as an option. Yarn takes the name positionally and has no joined
/// spelling, so there it rests on `ReleasePackageId`'s leading-`-` rejection.
///
/// `tag`/`access`/`registry` are appended to every variant's base args.
/// `package_dir` is only used for bun: it has no `--filter`/`--workspace`
/// flag to target one package by name, so it alone must run from the
/// package's own directory rather than the workspace root.
pub fn npm_publish_argv(
    workspace_root: &Path,
    package_dir: &Path,
    package_name: &str,
    package_manager: NpmPackageManager,
    tag: Option<&str>,
    access: Option<NpmAccess>,
    registry: Option<&str>,
) -> Argv {
    // `yarn npm publish` has no `--registry` option (it rejects one); the publish step refuses a configured registry
    // for yarn before it gets here, so nothing is dropped silently.
    let registry = registry.filter(|_| !matches!(package_manager, NpmPackageManager::Yarn));
    let extra = npm_publish_flags(package_name, tag, access, registry);

    let (program, mut args, cwd) = match package_manager {
        NpmPackageManager::Pnpm => (
            "pnpm",
            vec![
                "publish".to_string(),
                // `--filter=<name>`, not `--filter <name>`: the joined form
                // cannot be re-read as an option even if a name slipped past
                // `ReleasePackageId`'s charset rule.
                format!("--filter={package_name}"),
                // pnpm >= 7 refuses a dirty tree, and the tree is dirty after `callisto version` stages bumps.
                "--no-git-checks".to_string(),
            ],
            workspace_root.to_path_buf(),
        ),
        NpmPackageManager::Yarn => (
            "yarn",
            vec![
                "workspace".to_string(),
                package_name.to_string(),
                "npm".to_string(),
                "publish".to_string(),
            ],
            workspace_root.to_path_buf(),
        ),
        NpmPackageManager::Bun => ("bun", vec!["publish".to_string()], workspace_root.join(package_dir)),
        NpmPackageManager::Npm => (
            "npm",
            vec!["publish".to_string(), format!("--workspace={package_name}")],
            workspace_root.to_path_buf(),
        ),
    };
    args.extend(extra);
    Argv {
        program: program.to_string(),
        args,
        cwd,
    }
}

/// The access an npm package publishes with: the explicit `publishConfig.access`,
/// else `public` for a scoped `@scope/name` (npm defaults scoped packages to restricted).
pub fn npm_default_access(name: &str, explicit: Option<NpmAccess>) -> Option<NpmAccess> {
    explicit.or_else(|| name.starts_with('@').then_some(NpmAccess::Public))
}

/// `--tag`/`--access`/`--registry`, shared by every npm-ecosystem publish argv.
fn npm_publish_flags(
    package_name: &str,
    tag: Option<&str>,
    access: Option<NpmAccess>,
    registry: Option<&str>,
) -> Vec<String> {
    let mut extra: Vec<String> = Vec::new();
    if let Some(t) = tag {
        extra.push("--tag".to_string());
        extra.push(t.to_string());
    }
    if let Some(access) = npm_default_access(package_name, access) {
        extra.push("--access".to_string());
        extra.push(
            match access {
                NpmAccess::Public => "public",
                NpmAccess::Restricted => "restricted",
            }
            .to_string(),
        );
    }
    if let Some(reg) = registry {
        extra.push("--registry".to_string());
        extra.push(reg.to_string());
    }
    extra
}

/// Publishes the package in `package_dir` by path: `npm publish <dir>` from `workspace_dir` (the workspace that owns
/// it, where its `.npmrc` is read), whatever the package manager. pnpm `--filter`, yarn
/// `workspace`, and npm `--workspace` select only workspace members, and an npm
/// platform package directory usually is not one. The path is absolute, so it
/// cannot be read as an option.
pub fn npm_publish_directory_argv(
    workspace_root: &Path,
    workspace_dir: &Path,
    package_dir: &Path,
    package_name: &str,
    tag: Option<&str>,
    access: Option<NpmAccess>,
    registry: Option<&str>,
) -> Argv {
    let mut args = vec![
        "publish".to_string(),
        workspace_root.join(package_dir).to_string_lossy().into_owned(),
    ];
    args.extend(npm_publish_flags(package_name, tag, access, registry));
    Argv {
        program: "npm".to_string(),
        args,
        cwd: workspace_root.join(workspace_dir),
    }
}

// ----------------------------------------------------------------- pypi

/// `python -m build --sdist --wheel --outdir <outdir>` in the package directory, with the first interpreter on PATH
/// and `SOURCE_DATE_EPOCH` set so backends that honor it stamp the same time into every rebuild.
pub fn pypi_build_argv(
    workspace_root: &Path,
    package_dir: &Path,
    outdir: &Path,
    source_date_epoch: u64,
) -> Result<Argv, GraphError> {
    let interpreter = resolve_python_interpreter(std::env::var_os("PATH").as_deref())?;
    Ok(Argv {
        program: "env".to_string(),
        args: vec![
            format!("SOURCE_DATE_EPOCH={source_date_epoch}"),
            interpreter.to_string(),
            "-m".to_string(),
            "build".to_string(),
            "--sdist".to_string(),
            "--wheel".to_string(),
            "--outdir".to_string(),
            outdir.to_string_lossy().into_owned(),
        ],
        cwd: workspace_root.join(package_dir),
    })
}

/// `twine upload` of exactly `files`, never a glob or `--skip-existing`, which skips by name without comparing bytes.
pub fn pypi_upload_argv(workspace_root: &Path, package_dir: &Path, index: Option<&str>, files: &[PathBuf]) -> Argv {
    let mut args = vec!["upload".to_string()];
    if let Some(index) = index {
        args.push("--repository-url".to_string());
        args.push(index.to_string());
    }
    args.extend(files.iter().map(|file| file.to_string_lossy().into_owned()));
    Argv {
        program: "twine".to_string(),
        args,
        cwd: workspace_root.join(package_dir),
    }
}

/// Resolves the interpreter for the PyPI build step's `python -m build`:
/// prefers `python3` -- the only name macOS and Debian systems guarantee --
/// and falls back to bare `python` for systems that only ship that. Errors
/// naming both when neither is on `path_value`.
///
/// `path_value` is injected rather than read from `$PATH` directly so tests
/// can exercise both resolutions and the error without mutating process-wide
/// environment state.
fn resolve_python_interpreter(path_value: Option<&OsStr>) -> Result<&'static str, GraphError> {
    if exists_on_path("python3", path_value) {
        Ok("python3")
    } else if exists_on_path("python", path_value) {
        Ok("python")
    } else {
        Err(GraphError::ReleasePreconditionUnmet {
            requirement: ReleasePreconditionRequirement::PythonInterpreterOnPath,
        })
    }
}

/// Whether `program` exists as a file in some directory of `path_value` --
/// PATH-lookup semantics, without ever spawning it.
fn exists_on_path(program: &str, path_value: Option<&OsStr>) -> bool {
    path_value.is_some_and(|path| std::env::split_paths(path).any(|dir| dir.join(program).is_file()))
}

// ---- shared output-classification helpers --------------------------------

fn combined_lower(output: &CommandOutput) -> String {
    format!("{}\n{}", output.stdout, output.stderr).to_lowercase()
}

/// What a failed publish said: the last lines of redacted stdout, then redacted stderr. pnpm and twine print their
/// errors to stdout, so stderr alone can leave the failure message empty.
fn failure_detail(output: &CommandOutput) -> String {
    const STDOUT_TAIL_LINES: usize = 8;
    let stdout = callisto_model::redact_command_stderr(&output.stdout);
    let tail: Vec<&str> = stdout.lines().rev().take(STDOUT_TAIL_LINES).collect();
    let tail = tail.into_iter().rev().collect::<Vec<_>>().join("\n");
    let stderr = output.redacted_stderr();
    [tail.trim(), stderr.trim()]
        .into_iter()
        .filter(|part| !part.is_empty())
        .collect::<Vec<_>>()
        .join("\n")
}

/// Parses a numeric retry-after value (seconds) as reported by a registry
/// tool's output.
fn parse_retry_after(raw: &str) -> Option<Duration> {
    raw.trim().parse::<u64>().ok().map(Duration::from_secs)
}

/// Looks for a `retry after <N>` mention in already-lowercased text and
/// parses `<N>` as a whole-second duration.
fn extract_retry_after_duration(text_lower: &str) -> Option<Duration> {
    const NEEDLE: &str = "retry after ";
    let idx = text_lower.find(NEEDLE)?;
    let rest = &text_lower[idx + NEEDLE.len()..];
    let token = rest.split_whitespace().next()?;
    let digits: String = token.chars().take_while(|c| c.is_ascii_digit()).collect();
    if digits.is_empty() {
        return None;
    }
    parse_retry_after(&digits)
}

fn detect_rate_limit(text_lower: &str) -> Option<RegistryError> {
    // Match rate-limit text with context; a bare "429" appears in cargo's size output ("429.1KiB").
    let is_rate_limited = text_lower.contains("too many requests")
        || text_lower.contains("rate limit")
        || text_lower.contains("erate_limit")
        || (text_lower.contains("429")
            && (text_lower.contains("too many") || text_lower.contains("rate") || text_lower.contains("retry")));
    if is_rate_limited {
        let dur = extract_retry_after_duration(text_lower).unwrap_or(Duration::from_secs(DEFAULT_RATE_LIMIT_WAIT_SECS));
        Some(RegistryError::RateLimited(dur))
    } else {
        None
    }
}

fn detect_auth_failure(text_lower: &str, raw_stderr: &CommandOutput) -> Option<RegistryError> {
    // Match 401/403 with context, like the 429 guard; byte counts and timings contain those digits.
    if (text_lower.contains("401") && text_lower.contains("auth"))
        || (text_lower.contains("403") && (text_lower.contains("auth") || text_lower.contains("forbidden")))
        || text_lower.contains("authentication")
        || text_lower.contains("not logged in")
        || text_lower.contains("invalid token")
        || text_lower.contains("forbidden")
    {
        Some(RegistryError::AuthFailed(raw_stderr.redacted_stderr()))
    } else {
        None
    }
}

/// Classifies combined `cargo publish` output into a [`PublishOutcome`] or
/// [`RegistryError`].
pub(crate) fn classify_cargo_output(output: &CommandOutput) -> Result<PublishOutcome, RegistryError> {
    let combined = combined_lower(output);

    // Success first: only a failed publish can mean the version is already there, and a successful one may print
    // anything, including those words.
    if output.success() {
        return Ok(PublishOutcome::Published);
    }
    if combined.contains("already exists") || combined.contains("already uploaded") {
        return Ok(PublishOutcome::AlreadyPublished);
    }
    if let Some(err) = detect_rate_limit(&combined) {
        return Err(err);
    }
    if let Some(err) = detect_auth_failure(&combined, output) {
        return Err(err);
    }
    Err(RegistryError::Other(format!(
        "cargo publish failed (exit {:?}): {}",
        output.exit_code,
        failure_detail(output)
    )))
}

/// Classifies combined `npm publish` (or `pnpm`/`yarn`/`bun` equivalent)
/// output into a [`PublishOutcome`] or [`RegistryError`].
pub(crate) fn classify_npm_publish_output(output: &CommandOutput) -> Result<PublishOutcome, RegistryError> {
    let combined = combined_lower(output);

    // Success first, as for cargo. On failure only npm's own conflict signals count: a bare `e409` can sit in a bundle
    // name or hash.
    if output.success() {
        return Ok(PublishOutcome::Published);
    }
    if combined.contains("code e409")
        || combined.contains("code epublishconflict")
        || combined.contains("cannot publish over the previously published versions")
    {
        return Ok(PublishOutcome::AlreadyPublished);
    }
    if let Some(err) = detect_rate_limit(&combined) {
        return Err(err);
    }
    if let Some(err) = detect_auth_failure(&combined, output) {
        return Err(err);
    }
    Err(RegistryError::Other(format!(
        "npm publish failed (exit {:?}): {}",
        output.exit_code,
        failure_detail(output)
    )))
}

/// Classifies combined `twine upload` output into a [`PublishOutcome`] or
/// [`RegistryError`].
///
/// Priority order (highest wins):
/// 1. A successful run printing `"already exist"` (twine's `--skip-existing` message) without `"uploading"` ->
///    [`PublishOutcome::AlreadyPublished`]. Callisto passes no `--skip-existing`, so a conflict is a failing run and
///    falls through to `RegistryError::Other` below, which is the intended fail-closed outcome.
/// 2. Zero exit code with no skip-only mention -> [`PublishOutcome::Published`].
/// 3. Rate-limit signal (`429`, `too many requests`, `rate limit`) ->
///    [`RegistryError::RateLimited`] with a parsed or default 60-second
///    retry-after duration.
/// 4. Auth-failure signal (`401`, `403`, `authentication`, etc.) ->
///    [`RegistryError::AuthFailed`].
/// 5. Anything else -> [`RegistryError::Other`].
pub(crate) fn classify_twine_output(output: &CommandOutput) -> Result<PublishOutcome, RegistryError> {
    let combined = combined_lower(output);

    let has_skip = combined.contains("already exist");
    let has_upload = combined.contains("uploading");
    if has_skip && !has_upload && output.success() {
        return Ok(PublishOutcome::AlreadyPublished);
    }
    if output.success() {
        return Ok(PublishOutcome::Published);
    }
    if let Some(err) = detect_rate_limit(&combined) {
        return Err(err);
    }
    if let Some(err) = detect_auth_failure(&combined, output) {
        return Err(err);
    }
    Err(RegistryError::Other(format!(
        "twine upload failed (exit {:?}): {}",
        output.exit_code,
        failure_detail(output)
    )))
}

