269	            ProviderObservationV1::Indeterminate {
270	                cause: ProviderIndeterminateCause::UnsupportedProvider,
271	            } => Ok(proceed()),
272	            observation => preflight_from_observation(observation, id, RemoteConflict::RegistryVersionDiffers),
