279	        &self,
280	        context: &ProviderContext<'_>,
281	        _id: &ReleaseOperationId,
282	        operation: &RegistryPublishOperation,
283	        _artifacts: Option<&VerifiedArtifactManifest<'_>>,
284	    ) -> Result<ProviderObservationV1, GraphError> {
