294	pub(crate) fn recorded_repository(
295	    context: &ProviderContext<'_>,
296	    ecosystem: Ecosystem,
297	    operation: &RegistryPublishOperation,
298	) -> Option<String> {
299	    adapter_for(ecosystem).ok()?.repository(context, operation)
300	}

