33	pub(super) struct PypiRegistry;
34	
35	/// PyPI's own PEP 691 JSON simple index, not `pip`: `pip index versions` is
36	/// experimental and hides yanked releases, and an unreachable index and a
37	/// missing project both look like "no versions found" to it. The index itself
38	/// answers plainly -- 200 with a `files[]` entry naming the version, or 404 --
39	/// so observation goes straight to `https://pypi.org/simple/<project>/`
40	/// (or the configured private index) over `curl`, never through `pip`.
41	pub(super) const PYPI_DEFAULT_SIMPLE_INDEX: &str = "https://pypi.org/simple";
42	
43	/// PEP 691: the versioned JSON media type, so the index cannot fall back to
44	/// the legacy HTML page a bare GET would otherwise serve.
45	pub(super) const PYPI_SIMPLE_ACCEPT: &str = "application/vnd.pypi.simple.v1+json";
46	
47	/// The project's simple-index URL: the configured private index if one is
48	/// bound (already https-validated in `binding.rs`), else the public default.
49	pub(super) fn pypi_simple_index_url(endpoint: Option<&str>, package_name: &str) -> String {
50	    let base = endpoint.unwrap_or(PYPI_DEFAULT_SIMPLE_INDEX);
51	    let project = normalize_pypi_project_name(package_name);
52	    format!("{}/{project}/", base.trim_end_matches('/'))
53	}
54	
55	/// The version segment of a simple-index filename, or `None` for an extension
56	/// this parser does not recognize (a legacy installer, say).
57	pub(super) fn pypi_simple_file_version(filename: &str) -> Option<&str> {
58	    callisto_model::pypi_dist_filename_parts(filename).map(|(_, version)| version)
59	}
60	
61	/// Whether a simple-index file's filename names exactly the requested version.
62	pub(super) fn pypi_simple_file_matches(file: &PypiSimpleFile, version: &Version) -> bool {
63	    pypi_simple_file_version(&file.filename).is_some_and(|candidate| {
64	        Version::parse(candidate, version.grammar())
65	            .is_ok_and(|candidate| candidate.compare(version) == Ok(std::cmp::Ordering::Equal))
66	    })
67	}
68	
69	/// Classifies a parsed 200 body: the matching file's yank status decides the
70	/// answer, mirroring cargo's yanked-is-absent rationale above -- a yanked
71	/// release is not the version this intent authorized, so it fails closed.
72	pub(super) fn classify_pypi_simple_body(body: &str, version: &Version) -> Attempt<ProviderObservationV1> {
73	    let Ok(index) = serde_json::from_str::<PypiSimpleIndex>(body) else {
74	        return transient(ProviderIndeterminateCause::MalformedResponse, None);
75	    };
76	    let matching = index
77	        .files
78	        .iter()
79	        .filter(|file| pypi_simple_file_matches(file, version));
80	    let mut matched = false;
81	    for file in matching {
82	        if file.is_yanked() {
83	            return settled(ProviderObservationV1::Absent);
84	        }
85	        matched = true;
86	    }
87	    if !matched {
88	        return settled(ProviderObservationV1::Absent);
89	    }
90	    settled(exact_version(version))
91	}
92	
93	/// The observation that a version is on the registry, unyanked.
94	pub(super) fn exact_version(version: &Version) -> ProviderObservationV1 {
95	    ProviderObservationV1::Exact {
96	        evidence: ProviderEvidenceV1::RegistryVersion {
97	            version: version.clone(),
98	            checksum: None,
99	            yanked: Some(false),
100	        },
101	    }
102	}
103	
104	/// What the index holds for one release.
105	pub(super) enum PypiRemote {
106	    Absent,
107	    Files(Vec<PypiSimpleFile>),
108	    Indeterminate(ProviderIndeterminateCause),
109	}
110	
111	/// The release's own files from a parsed 200 body.
112	pub(super) fn classify_pypi_files_body(body: &str, version: &Version) -> Attempt<PypiRemote> {
113	    let Ok(index) = serde_json::from_str::<PypiSimpleIndex>(body) else {
114	        return Attempt::Transient {
115	            value: PypiRemote::Indeterminate(ProviderIndeterminateCause::MalformedResponse),
116	            retry_after: None,
117	        };
118	    };
119	    let files: Vec<_> = index
120	        .files
121	        .into_iter()
122	        .filter(|file| pypi_simple_file_matches(file, version))
123	        .collect();
124	    Attempt::Settled(if files.is_empty() {
125	        PypiRemote::Absent
126	    } else {
127	        PypiRemote::Files(files)
128	    })
129	}
130	
131	/// Classifies one `curl -sS -i` run against the simple index. A private index
132	/// that ignores `Accept` and serves its legacy HTML page fails the JSON parse
133	/// inside `on_ok` and reads as `MalformedResponse`, same as any other body PEP
134	/// 691 JSON parsing cannot make sense of.
135	///
136	/// Any other status shares [`HttpResponse::is_transient`] with GitHub's `gh api` reads, so it retries on
137	/// `Retry-After` instead of settling immediately, and either way reports the status as `ProviderStatus`.
138	pub(super) fn classify_pypi_status<T>(
139	    output: &CommandOutput,
140	    on_ok: impl FnOnce(&str) -> Attempt<T>,
141	    absent: T,
142	    indeterminate: impl Fn(ProviderIndeterminateCause) -> T,
143	) -> Attempt<T> {
144	    let response = match parse_http_response(&output.stdout) {
145	        Ok(response) => response,
146	        Err(_) if !output.success() => {
147	            return Attempt::Transient {
148	                value: indeterminate(ProviderIndeterminateCause::CommandFailed),
149	                retry_after: None,
150	            }
151	        }
152	        Err(_) => {
153	            return Attempt::Transient {
154	                value: indeterminate(ProviderIndeterminateCause::MalformedResponse),
155	                retry_after: None,
156	            }
157	        }
158	    };
159	    match response.status {
160	        200 => on_ok(&response.body),
161	        404 => Attempt::Settled(absent),
162	        status if response.is_transient() => Attempt::Transient {
163	            value: indeterminate(ProviderIndeterminateCause::ProviderStatus { status }),
164	            retry_after: response.retry_after(),
165	        },
166	        status => Attempt::Settled(indeterminate(ProviderIndeterminateCause::ProviderStatus { status })),
167	    }
168	}
