189	    /// One `curl` of the project's simple index; `Err` when the command could not run at all.
190	    fn fetch_once(
191	        context: &ProviderContext<'_>,
192	        operation: &RegistryPublishOperation,
193	    ) -> Result<Result<CommandOutput, policy::CommandUnavailable>, GraphError> {
194	        let url = pypi_simple_index_url(operation.registry.endpoint.as_deref(), &operation.package_name);
195	        let accept_header = format!("Accept: {PYPI_SIMPLE_ACCEPT}");
196	        let args = ["-sS", "-i", "-H", accept_header.as_str(), url.as_str()];
197	        run_observation(
198	            context.runner(),
199	            programs::CURL,
200	            &args,
201	            context.root(),
202	            timeouts::REGISTRY_QUERY,
203	            false,
204	        )
205	    }
206	
207	    /// One look at the release's files on the index.
208	    fn remote_once(
209	        context: &ProviderContext<'_>,
210	        operation: &RegistryPublishOperation,
211	    ) -> Result<Attempt<PypiRemote>, GraphError> {
212	        Ok(match Self::fetch_once(context, operation)? {
213	            Ok(output) => classify_pypi_files(&output, &operation.version),
214	            Err(_unavailable) => Attempt::Transient {
215	                value: PypiRemote::Indeterminate(ProviderIndeterminateCause::CommandFailed),
216	                retry_after: None,
217	            },
218	        })
219	    }
