221	    /// The release's files on the index, retried on a transient failure.
222	    fn remote(context: &ProviderContext<'_>, operation: &RegistryPublishOperation) -> Result<PypiRemote, GraphError> {
223	        policy::retry_observation_within(context.sleeper(), context.patience(), || {
224	            Self::remote_once(context, operation)
225	        })
226	    }
