228	    /// The files of this release, once per run: the build job's sealed set when the manifest has one, else a build.
229	    fn built_set(
230	        context: &ProviderContext<'_>,
231	        id: &ReleaseOperationId,
232	        operation: &RegistryPublishOperation,
233	        artifacts: Option<&VerifiedArtifactManifest<'_>>,
234	    ) -> Result<Arc<BuiltSet>, GraphError> {
235	        let sets = context.file_sets().ok_or_else(|| GraphError::ReleaseInvariant {
236	            detail: "a Python release needs the per-run file set cache".to_string(),
237	        })?;
238	        sets.get_or_build(
239	            (operation.package_dir.clone(), operation.version.render().to_string()),
240	            || match artifacts.and_then(|artifacts| artifacts.sealed_files(&id.package, &operation.version)) {
241	                Some(files) => BuiltSet::sealed(
242	                    files
243	                        .into_iter()
244	                        .map(|file| BuiltFile {
245	                            filename: file.filename,
246	                            path: file.path,
247	                            sha256: file.sha256,
248	                        })
249	                        .collect(),
250	                    &operation.package_name,
251	                    &operation.version,
252	                ),
253	                None => {
254	                    if artifacts.is_some() {
255	                        eprintln!(
256	                            "warning: the artifact manifest does not seal {} {}; building it in this job",
257	                            operation.package_name,
258	                            operation.version.render()
259	                        );
260	                    }
261	                    Self::build_set(context, operation)
262	                }
263	            },
264	        )
265	    }
266	
267	    /// Builds the sdist and wheel into a fresh directory, so a stale `dist/` can never reach the upload.
268	    fn build_set(context: &ProviderContext<'_>, operation: &RegistryPublishOperation) -> Result<BuiltSet, GraphError> {
269	        let dir = tempfile::tempdir().map_err(|error| {
270	            GraphError::Command(callisto_model::CommandError::Io {
271	                program: "python -m build".to_string(),
272	                message: error.to_string(),
273	            })
274	        })?;
275	        Self::build_into(context, operation, dir.path())?;
276	        BuiltSet::from_dir(dir, &operation.package_name, &operation.version)
277	    }
278	
279	    /// Runs the build into `outdir`, with file timestamps pinned to the release commit.
280	    pub(crate) fn build_into(
281	        context: &ProviderContext<'_>,
282	        operation: &RegistryPublishOperation,
283	        outdir: &std::path::Path,
284	    ) -> Result<(), GraphError> {
285	        let epoch = callisto_model::vcs::GitAccess::new(context.root(), context.runner()).commit_time("HEAD")?;
286	        let build = registry_argv::pypi_build_argv(context.root(), &operation.package_dir, outdir, epoch)?;
287	        let built = run_build_argv(context, &build)?;
288	        if built.exit_code != Some(0) {
289	            return Err(GraphError::ReleaseCommand {
290	                program: build.program.clone(),
291	                args: build.args.clone(),
292	                failure: CommandFailure::NonZeroExit {
293	                    exit_code: built.exit_code,
294	                    stderr: built.stderr,
295	                },
296	            });
297	        }
298	        Ok(())
299	    }
300	}
