815	/// The text of `job`'s block: from its `  <job>:` line to the next job's.
816	fn job<'a>(workflow: &'a str, job: &str) -> &'a str {
817	    let start = workflow
818	        .find(&format!("\n  {job}:\n"))
819	        .unwrap_or_else(|| panic!("no job `{job}`"))
820	        + 1;
821	    let rest = &workflow[start..];
822	    let end = rest
823	        .match_indices("\n  ")
824	        .find(|(index, _)| !rest[index + 3..].starts_with(' '))
825	        .map_or(rest.len(), |(index, _)| index);
826	    &rest[..end]
827	}
